-- Telegram account linking foundation.
-- Tokens are generated by the authenticated PHP API, stored only as SHA-256 hashes,
-- and consumed atomically by the server-side webhook after Telegram confirms the user.
BEGIN;

CREATE TABLE IF NOT EXISTS public.telegram_account_link_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  token_hash char(64) NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT telegram_account_link_token_hash_format CHECK (token_hash ~ '^[a-f0-9]{64}$'),
  CONSTRAINT telegram_account_link_token_expiry CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS telegram_account_link_tokens_user_created_idx
  ON public.telegram_account_link_tokens (user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS telegram_account_link_tokens_expiry_idx
  ON public.telegram_account_link_tokens (expires_at)
  WHERE consumed_at IS NULL;

CREATE TABLE IF NOT EXISTS public.telegram_accounts (
  telegram_user_id bigint PRIMARY KEY CHECK (telegram_user_id > 0),
  user_id uuid NOT NULL UNIQUE REFERENCES public.users(id) ON DELETE CASCADE,
  username text,
  first_name text,
  linked_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

REVOKE ALL ON TABLE public.telegram_account_link_tokens FROM PUBLIC, anon, authenticated;
REVOKE ALL ON TABLE public.telegram_accounts FROM PUBLIC, anon, authenticated;

COMMENT ON TABLE public.telegram_account_link_tokens IS
  'Short-lived one-time tokens for explicit Telegram account linking; token_hash only, never raw token.';
COMMENT ON TABLE public.telegram_accounts IS
  'Server-managed Telegram identity linked to one existing MEDBIOHIM account. No browser direct access.';

NOTIFY pgrst, 'reload schema';
COMMIT;
